pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space avoidance on tiny residuals (super-linear penalty).
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Tight-fill reward (quadratic coupling with residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0 + fill_ratio * fill_ratio * 10.0;

    // Lookahead: exact next-item fit is extremely valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 6.0;
            } else if slack <= 8 {
                score -= 2.5;
            }
        } else {
            score += 10.0;
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
    }

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure, softened when many bins are already open.
    let open_pressure = if open_bins_count > 6 { 0.8 } else { 1.5 };
    score += open_bins_count as f64 * open_pressure;

    // Residual-ratio shaping vs mean residual (only for real bins).
    let mean_res = mean_residual.max(1.0);
    let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }

        // NEW: harsher penalty for large dead fractions that cannot fit next item.
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 8.0 * (dead_frac - 0.35).min(0.6);
        }

        // Fragmentation guard: residual that cannot host next item, penalize gap.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
    }

    // New-bin candidate logic, progress-aware.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 20.0;
        if post_residual < 10 {
            score -= 80.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        // NEW: prefer reusing open bins with decent fits late in stream.
        if fitting_bins_count > 0 && progress > 0.6 {
            score += 12.0 * progress;
        }
    }

    // Two-step lookahead: residual after placing next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 3.0;
            }
        }
        // NEW: reward near-perfect two-step consumption.
        if two_step <= 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(1) * 10 {
            score += 200.0 * (10.0 - post_residual as f64);
        }
        // Nonlinear penalty: tiny gaps are worthless.
        if post_residual <= 20 {
            score += (21.0 - post_residual as f64).powi(3) * 0.5;
        }
    } else {
        // Perfect fit is excellent.
        score -= 150.0;
    }

    // Reward tight fits (large item fraction of bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 4.0 * pressure;

    // If bin is brand-new candidate, add fixed cost so it's chosen only when clearly better.
    if bin_residual == bin_capacity {
        score += 90.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // If next item is large and this bin would be left with awkward residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Slight preference to fill bins earlier in stream progression.
    score += 10.0 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are wasted forever. Penalize them super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: item consuming most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin
    // only when the fit is bad. Encourage consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: neutral-ish baseline; only attractive when the fit
    // into existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // New bin: score = full remaining capacity, no dead-space penalty yet.
        // Make it slightly worse than a good fit but better than a terrible one.
        score = bin_capacity as f64 - 20.0;
        if post_residual < 10 {
            // existing-bin placement would be dead space; new bin wins
            score -= 80.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0; // existing bins fit decently, keep using them
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit into post residual and this bin would
    // then be stranded with tiny leftover.
    if next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for filling bins that are already mostly empty (large
    // residual) to consolidate load.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        if dead_frac > 0.35 {
            score += 12.0 * (dead_frac - 0.35);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unreachable = (next_item_size - post_residual) as f64;
            if unreachable > 15.0 {
                score += 0.4 * unreachable.min(40.0);
            }
        }
        let fill = 1.0 - dead_frac;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fill > 0.9 {
            score -= (10.0 + 6.0 * progress) * (fill - 0.9);
        }
        // borrowed: stronger near-perfect bonus when few bins compete
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // stranding risk: residual just below next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        // reusable residual bands
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
    }

    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 45 {
            let min_dead = if post_residual < next_item_size {
                (next_item_size - post_residual) as f64
            } else {
                0.0
            };
            if min_dead > 0.3 * bin_capacity as f64 {
                score -= 14.0;
            }
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 12.0;
        }
        // refined: open new bin early if all fitting options would strand large next items
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        // refined: penalize new-bin residuals too small to ever host mid-size items
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
    }

    // Two-step lookahead with chaining rewards
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
        let chain_frac = two_step as f64 / bin_capacity.max(1) as f64;
        if chain_frac > 0.3 {
            score -= 3.0 * chain_frac.min(0.8);
        }
    }

    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which fraction-of-capacity band does it fall in?
    let item_class = item_size / 10; // 0..=10 (item sizes 1..100)
    let post_class = post_residual / 10; // 0..=10

    // Reward placements that leave post_residual in "usable" harmonic classes:
    // post residuals that are multiples of common item sizes (multiples of 10)
    // are more likely to be exactly filled by future items.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.0;
    }

    // Penalize dead space: post_residual in awkward middle bands (11..29 mod 30)
    let awkward = post_residual % 30;
    if awkward >= 11 && awkward <= 29 {
        score += 4.0;
    }

    // Perfect fit is best
    if post_residual == 0 {
        score -= 25.0;
    }

    // Class matching: if post_residual class equals a plausible next-item class,
    // the next item may exactly consume it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // exact fill next step
        } else if next_item_size <= post_residual {
            let nclass = next_item_size / 10;
            if nclass == post_class && post_class > 0 {
                score -= 5.0;
            }
            score -= (post_residual as f64) * 0.05;
        } else {
            // next item cannot fit here anyway; slightly favor keeping flexibility
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so we only
    // open a new bin when all open bins are tightly packed or would waste space.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins have small residuals
        // (high packing density) or few bins fit the item.
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * 0.55 - tightness * 20.0
            - (fitting_bins_count as f64) * 1.5
            - (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0; // big item coming: fresh bin useful
        }
        if post_residual == 0 {
            score = 1e9; // never "open" a bin for a zero-residual phantom
        }
    }

    // Slight preference for bins with below-mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

