        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        // If the only fitting bins would strand >30% dead space while the next
        // item is large, opening fresh is safer.
        if fitting_bins_count > 0 && next_item_size > 45 {
            let min_dead = if post_residual < next_item_size {
                (next_item_size - post_residual) as f64
            } else {
                0.0
            };
            if min_dead > 0.3 * bin_capacity as f64 {
                score -= 14.0;
            }
        }
        // NEW: prefer new bin when dead space would strand a large next item.
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 3.0;
            }
        }
        // Triple-chaining reward.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
