    // Lookahead: if next item fits exactly in post_residual, reward heavily (smooth via ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = nxt / (pr + 1.0);
        if fit_ratio <= 1.0 {
            score -= 2.5 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 - 0.5 * progress);
