    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        // abundance of alternatives: slight penalty for wasting a scarce bin slot
        score += 0.15 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // Mean residual context: if this bin is far below mean residual, it's a "junk" bin —
    // placing here is fine (reward); if far above mean, penalize lightly.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.4 * dev;

    // New-bin candidate: encourage opening fresh bins early, discourage late when
    // open bins exist; smooth in progress and residual.
    if bin_residual == bin_capacity {
