        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Coupling with mean residual: if this bin is much emptier than average,
    // it's a good "donor" bin; prefer placing here keeps balance.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Small tie-breaking nudge toward fuller bins (lower residual).
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap: worst outcome
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits relative to bin capacity.
    score -= 35.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor dense fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).min(5.0);
    score += pressure * 4.0;

    // Lookahead: if next item fits this bin's post_residual, reward keeping it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 8.0; // leftover can't host next item: mild penalty
    }

    // New-bin candidate: only attractive when current fit is bad and pressure high.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 40.0;
        if bad_fit && open_bins_count > 2 {
            score -= 45.0;
        } else {
            score += 20.0;
        }
    }

    // Deviation from mean residual: prefer bins below mean (tighter bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match for the next item is nearly as good.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild bonus,
            // scaled by how much slack remains for the item after that.
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Next item cannot use this bin's remainder: penalize dead space
            // that is smaller than the smallest possible item (1..100 range).
            if post_residual < next_item_size {
                score += 30.0;
            }
        }
    }

    // Penalize small unusable remainders (dead space below typical item floor).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer bins whose residual is already below average (tighter bins close out).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Early in the stream, allow opening fresh bins more freely (better packing
    // later); late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
    }

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_frac;

    // Penalize small dead space that nothing (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover: penalize proportional to waste
            score += 0.5 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else {
        // mild penalty when many alternatives exist to encourage spreading
        score += 8.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, prefer tight fits / keep bins flexible;
    // late in stream, prefer closing out bins (larger post_residual penalty)
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.2 * post_residual as f64;
    score += t * 0.6 * post_residual as f64;

    // Global state: many open bins with high mean residual -> prefer new-ish consolidation
    if open_bins_count > 0 {
        let mean_res_norm = mean_residual / bin_capacity as f64;
        // if this bin's residual is far below mean, it's already fragmented; penalize
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 40.0 * dev;
        // when bins are crowded, discourage opening new bins implicitly via fit reward
        if mean_res_norm > 0.5 {
            score -= 20.0 * fill_frac;
        }
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        score -= 150.0 * fill_frac;
        if fill_frac < 0.3 {
            score += 300.0; // don't open a bin for tiny items
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Base: reward tight fits via squared post-residual penalty
    let mut score = post * post / cap;

    // Smooth coupling of fill with stream progress: later in stream, prefer fuller bins
    score -= 18.0 * fill * fill * (0.5 + progress);

    // Penalize post residual that is too small to be useful later (dead space) — smooth term
    let dead = (1.0 - (post / 20.0).min(1.0)).max(0.0);
    score += 25.0 * dead * dead * (1.0 - progress);

    // Lookahead: if next item fits exactly in post residual, reward strongly (smooth gaussian-like)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (-(gap * gap) / 120.0).exp();
    }

    // Last-chance bin bonus (smooth in fitting count)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: make it unattractive unless post residual is large and stream is early
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).max(0.0);
        score += 8.0 + 10.0 * (1.0 - early);
        score -= 6.0 * (-(item_size as f64 * item_size as f64) / 2000.0).exp() * early;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into harmonic bands.
    // Classes 0 (perfect fit) through 3 (large residual) get class-based rewards.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1 fraction of capacity remaining

    // Integer-division harmonic class on post_residual (band width 12):
    // class 0: <=12, class 1: <=24, class 2: <=36, class 3+: waste
    let band = post_residual / 12;
    let band_reward: f64 = match band {
        0 => 60.0,           // near-perfect fit, strongly reward
        1 => 40.0,           // still tight
        2 => 20.0,           // moderate
        3 => 5.0,            // acceptable
        _ => 0.0,            // large dead space
    };
    score -= band_reward;

    // Modulo arithmetic: residuals that are "harmonic" with common item sizes
    // (multiples of 10) are more reusable. Reward post_residual divisible by 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize residuals in awkward small zone (1..10) — dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic: next item leaves another small residual
            if gap <= 12 {
                score -= 30.0;
            } else if gap <= 25 {
                score -= 10.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // next item cannot use this residual at all: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only prefer a new bin if all open bins would leave big waste.
    if bin_residual == bin_capacity {
        // baseline penalty so a new bin is chosen only when genuinely better
        score += 45.0;
        // but if stream is early and few bins open, opening is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for bins tighter than average (concentrate waste).
    score += (mean_residual - post_f) * 0.3;

    // Mild pressure against accumulating many open bins with large residuals.
    if open_bins_count > 8 && post_f > 40.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Leaving a gap the next item cannot use: penalize proportionally.
        score += 8.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit (residual much larger than item) or the
    // stream is early. Otherwise keep it expensive.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 + 15.0;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.3;
        if decent_fit_exists && !early {
            score += 70.0;
        } else {
            score += 15.0;
        }
    }

    // Slight preference for bins already below mean residual (balance residuals).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item size (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: heavy bonus; near match: graded bonus.
        if diff == 0.0 {
            score -= 45.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item still fits after this placement: reward tightness.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item cannot use this bin's residual: penalize leftover dead space,
            // worse when residual is small (unusable fragment).
            let frag = post_residual as f64;
            if frag < 10.0 {
                score += 20.0;
            } else {
                score += 0.15 * frag;
            }
        }
    } else {
        // Last item: simply prefer tightest fill.
        score += 0.0;
    }

    // Prefer bins whose residual is already below average (consolidating fragmentation),
    // penalize dumping into unusually roomy bins unless the fit is very tight.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if only this bin can fit the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; discounted late in the stream is not
        // meaningful, so keep it flat but slightly reduced when many bins are open
        // and fragmented (mean residual low).
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 100.0 - 15.0 * fragmentation;
    }

    // Mild late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: relative waste
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Penalize creating small unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item still fits: mild reward proportional to how snug
            score -= (next_item_size as f64 / post_residual as f64) * 20.0;
        } else {
            // next item won't fit here: penalize leaving large residual that blocks nothing
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        // base penalty so new bins are only opened when beneficial
        score += 60.0;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // if many open bins with large mean residual, discourage new bin
        score += (mean_residual / bin_capacity as f64) * 50.0;
        // if item is large relative to capacity, new bin is fine
        score -= (item_size as f64 / bin_capacity as f64) * 70.0;
    }

    // Prefer filling bins that are already low on residual (best-fit flavor)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight preference for keeping number of open bins small
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: tight fit is good, but the value of tightness grows with stream progress.
    let mut score = norm_pr;

    // Non-linear polynomial coupling: quadratic post-residual penalty modulated by progress.
    // Early on, leftover space matters less; late in the stream, dead space is costly.
    score += 2.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward filling the bin deeply (cubic term), stronger as the stream matures.
    score -= 0.8 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 1.5 * (1.0 - fit_quality) * (1.0 - progress);
        score -= 1.0 * (1.0 - fit_quality) * progress;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Penalize leaving a residual that the next item cannot use (dead space risk).
        score += 0.5 * norm_pr * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Deviation from mean residual: prefer bins below mean (denser bins) with smooth coupling.
    let mean_norm = mean_residual / cap;
    score += 0.4 * (norm_pr - mean_norm) * (1.0 + progress);

    // New-bin candidate: only attractive when open bins are crowded and item is large.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        let fill_ratio = item_size as f64 / cap;
        score = 1.2 + 1.5 * (1.0 - crowd) - 0.8 * fill_ratio * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: classify post_residual into
    // capacity-fraction buckets. Gaps in "small" classes (< 25% capacity)
    // are nearly dead space -> penalize heavily.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if frac <= 0.10 {
        score -= 25.0; // tiny gap, almost full
    } else if frac <= 0.25 {
        score += 10.0; // dead-space zone
    } else if frac <= 0.50 {
        score -= 5.0; // half-ish gap still usable
    } else {
        score -= 15.0; // large residual, very reusable
    }

    // Integer-division harmonic classes of post_residual modulo common
    // item-size steps: gaps that are multiples of 10/20 align with
    // typical item sizes and get reused more easily.
    let pr = post_residual;
    if pr > 0 {
        if pr % 20 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 1.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how tight the follow-up fit is
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; slightly penalize wasting
            // a big residual on a small follow-up
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if the current item would leave a badly fragmented gap everywhere.
    if bin_residual == bin_capacity {
        // fresh bin: baseline is its full residual; make it unattractive
        // unless the item is large relative to capacity (big items pack
        // best in fresh bins) or few bins exist.
        let size_frac = item_size as f64 / cap;
        score -= 18.0 * size_frac; // big items favor fresh bins
        if open_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
        if frac > 0.5 {
            score += 25.0; // fresh-bin waste penalty when item is small
        }
    }

    // Stream progression: early in the stream, prefer keeping residuals
    // large and flexible; late in the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;
    score -= (1.0 - progress) * 3.0;

    // Mean-residual context: if open bins are generally loose, avoid
    // adding another loose bin; if they are tight, value reusability.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are wasted forever. Penalize them super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: item consuming most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin
    // only when the fit is bad. Encourage consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: neutral-ish baseline; only attractive when the fit
    // into existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // New bin: score = full remaining capacity, no dead-space penalty yet.
        // Make it slightly worse than a good fit but better than a terrible one.
        score = bin_capacity as f64 - 20.0;
        if post_residual < 10 {
            // existing-bin placement would be dead space; new bin wins
            score -= 80.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0; // existing bins fit decently, keep using them
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit into post residual and this bin would
    // then be stranded with tiny leftover.
    if next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for filling bins that are already mostly empty (large
    // residual) to consolidate load.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect chain), penalize wasted chain potential.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward closeness to a perfect chain.
            score -= (item_size as f64) * (1.0 - diff / (bin_capacity as f64)) * 0.6;
            if diff == 0.0 {
                score -= 25.0; // perfect 2-step chain bonus
            }
        } else {
            // Next item cannot use the residual: penalize dead space growth.
            score += diff * 0.15;
            // Extra penalty if residual becomes unusably small (dead space).
            if post_residual < 10 {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.1;
    }

    // Compare against mean residual: prefer bins tighter than average
    // when they still allow a good chain, discourage using loose bins poorly.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= 3.0;
    } else {
        score += (res_f - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discard opening a new bin unless it is genuinely better than any
    // open-bin chain: make new bins slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is huge and current residuals are tight,
        // new bin becomes relatively more attractive.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() as f64 > 30.0 {
            score -= 10.0;
