    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // elsewhere is poor. Make the empty-bin call mildly expensive, scaled by how
    // many open bins already exist (fragmentation pressure).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 55.0 + 10.0 * pressure;
