    // nudging toward consolidating fullness.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Many open bins: encourage closing bins out (prefer small residual bins) to
    // reduce fragmentation.
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 1.5 * fit_ratio;
