    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial core: penalize post residual, with progress-dependent weight
    let mut score = pr;

    // Non-linear coupling: dead space matters more as stream progresses
    let dead_weight = 0.5 + 2.0 * progress * progress;
    score += dead_weight * norm_pr * norm_pr * cap;

