    score -= (1.0 - progress) * (cap - pr) * 0.05;

    // Last-chance bonus: smooth sigmoid-like term
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far from mean residual (prefer balanced packing), smooth quadratic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Lookahead coupling: reward leaving space for next item, smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = if pr >= n { 1.0 } else { pr / n };
        score -= 6.0 * fit_next * fit_next * (0.5 + progress);
        // penalize leaving residual just barely below next item size
        let gap = (n - pr) / cap;
        if gap > 0.0 && gap < 0.2 {
            score += 8.0 * (1.0 - gap / 0.2) * (1.0 - gap / 0.2);
        }
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: residual capacity in capacity-fraction buckets.
    // Capacity 100 -> classes of 25 (quarters). Small post_residual in a
    // "wasted class" (<25) is nearly dead space; penalize more the smaller it is.
    let quarter = bin_capacity / 4;
    let cls = post_residual / quarter; // 0..=4
    score += match cls {
        0 => 40.0,                    // dead space < 25
        1 => 10.0,                    // 25..49, fits only tiny items
        2 => -5.0,                    // 50..74, decent class
        3 => -15.0,                   // 75..99, excellent class
        _ => -20.0,                   // exact fit / full residual
    };

    // Modulo arithmetic on post_residual: residuals divisible by small
    // integers (10, 20, 50) are more reusable by typical item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        // Odd, prime-like residuals are awkward; small penalty.
        if post_residual % 10 != 0 && post_residual < quarter { score += 8.0; }
    } else {
        // Perfect packing: bin closed, best outcome.
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: reward, stronger for larger next items consuming class space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 20.0 * fill;
        } else {
            // Next item won't fit here: if post_residual is in a dead class,
            // penalty for stranding it.
            if post_residual < next_item_size && post_residual < quarter {
                score += 15.0;
            }
