    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post_residual waste).
    if fitting_bins_count == 1 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - waste);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer it only when item is huge relative to mean residual of open bins,
    // i.e. open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open bins fragmented (low mean residual): new bin is attractive.
        score -= 12.0 * fragmentation;
        // Late in the stream, avoid spawning bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    } else {
        // Filling existing bins slightly favored early; more open bins -> more
        // incentive to consolidate.
        score -= 4.0 * (open_bins_count as f64).sqrt() / (1.0 + step_index as f64 / total_items.max(1) as f64);
    }

    score
}

