pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: extremely strong reward.
    if post_residual == 0 {
        score -= 900.0;
    }

    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item still fits after this placement: reward tightness.
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Next item cannot use this residual: penalize dead space.
            let frag = post_residual as f64;
            if frag < 10.0 {
                score += 20.0;
            } else {
                score += 0.15 * frag;
            }
            // Gap to next item: small gaps are recoverable, large ones wasteful.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
    }

    // Consolidate fragmentation: prefer bins whose residual is below average.
    let mean_res = mean_residual.max(1.0);
    let excess = (post_residual as f64 - mean_res) / mean_res;
    if excess > 1.1 {
        score += 18.0 * (excess - 1.1).min(3.2);
    } else if excess < -0.5 {
        score -= 4.0 * (-excess - 0.5).min(2.0);
    }

    // Dead-space fraction penalties, scaled by item size context.
    let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
    if dead_frac > 0.35 && next_item_size > post_residual {
        score += 12.0 * (dead_frac - 0.35);
    } else if dead_frac < 0.12 {
        score -= 6.0 * (0.12 - dead_frac);
    }
    let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
    if dead_frac > 0.25 && item_frac < dead_frac {
        score += 8.0 * (dead_frac - item_frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Two-step lookahead refinement: reward residuals that chain future items.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 3.0;
            }
        }
    }

    // New-bin candidate handling: open a fresh bin only when it promises a good
    // future chain or when open bins are hopelessly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_res / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 15.0 * fragmentation;
        // Prefer new bin when next item is large and would be stranded otherwise.
        if next_item_size > post_residual.min(60) && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        // Late stream: opening new bins is costly.
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
    }

    // Mild late-stream tightening: fill existing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

