pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Reward residual capacity that can plausibly host future items.
        score -= 0.5 * post_residual as f64;
    }

    // Reward bins whose residual after placement still fits the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * (next_item_size as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement would destroy space needed by the next item.
            score += 12.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high or many bins fit the item.
        score += 25.0 + 3.0 * pressure + 8.0 * fitting_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly prefer using it over opening a new bin.
        score -= 30.0;
    }

    // Late in the stream, tighten up: avoid leaving scattered small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual to next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Exact fill after next item: heavily reward.
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this one: reward proportionally to tightness.
            let slack = post - nxt;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leftover that is likely dead space (too small for typical items).
            if slack < 10.0 {
                score += 40.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize, worse if very little space left.
            let waste = nxt - post;
            score += 25.0 + waste.min(50.0);
        }
    } else {
        // Last item: prefer exact fill.
        if post_residual == 0 {
            score -= 150.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item also fits nicely in a fresh bin, slightly encourage opening.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that can't plausibly be filled later.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small dead space is fine (near-perfect fill)
    } else if post_residual >= 10 {
        // post_residual in [10, ~30] is reusable; large leftovers are wasteful.
        score += 0.35 * (post_residual as f64 - 30.0).max(0.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 30.0; // perfect chaining
            } else {
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else if next_item_size >= post_residual && post_residual < 10 {
            score += 5.0; // creates unusable sliver for the known next item
        }
    }

    // Time horizon: early in the stream, keep flexibility (mild penalty for fragmentation);
    // late in the stream, prioritize closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fit_ratio;

    // Crowding: when many bins are open, prefer consolidating into fuller bins.
    if open_bins_count > 4 {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 12.0 * fullness;
    }

    // Mean-residual coupling: if this bin is fuller than average, favor it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: only open a new bin when the item is small relative
    // to capacity AND no decently fitting open bin exists (fitting_bins_count small)
    // and the stream is still young enough to justify a fresh bin.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_small = item_size as f64 / bin_capacity as f64;
        if scarcity > 0.0 || (fitting_bins_count <= 2 && item_small < 0.35 && progress < 0.5) {
            score -= 20.0 * scarcity + 10.0 * (1.0 - item_small);
        } else {
            score += 45.0; // strongly discourage opening a new bin when fits exist
        }
    }

    score
}

