pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance: residuals too small for plausible items are wasted.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual-relative analysis for open bins.
    let mean_res = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // NEW: mid-range dead zones (20..40% of capacity) are the biggest waste
        // source; penalize proportionally unless next item chains into them.
        if dead_frac >= 0.2 && dead_frac <= 0.4 {
            let chains = next_item_size > 0 && post_residual >= next_item_size;
            if !chains {
                score += 14.0 * (dead_frac - 0.2);
            }
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        // Prefer opening a fresh bin when all fitting bins would strand
        // a large dead zone relative to the next item's needs.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = (post_residual.saturating_sub(next_item_size)) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0; // near-perfect chaining exists; avoid new bin
            }
        }
        // NEW: discourage new bin when an open bin would leave a hole the
        // next item can still absorb (lookahead chaining beats fresh space).
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 3.0;
            }
        }
        // Triple-chaining reward when residual can absorb item + next + more.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        // NEW: exact-size chain bonus — residual after next item matches a
        // plausible small item range, maximizing compaction.
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, quadratically (dead space grows expensive).
    let mut score = norm_pr + 1.75 * norm_pr * norm_pr;

    // Smooth cubic coupling of residual with stream progress:
    // early on, prefer tight fills less aggressively; late, reward tight fills strongly.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score -= 1.2 * prog_poly * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: if next item fits exactly in post_residual, reward heavily (smooth via ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = nxt / (pr + 1.0);
        if fit_ratio <= 1.0 {
            score -= 2.5 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 - 0.5 * progress);
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            score += 0.6 * (fit_ratio - 1.0).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
