        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's remainder: penalize slightly more for large residuals
        score += 3.0 + post_residual as f64 / 25.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
