pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - gap) * 0.6;
        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item cannot use
