pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly: small post-residuals are cheap,
    // but residuals that can never fit a typical item are expensive.
    let dead_zone = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += 60.0 * dead_zone;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting the slot.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and we want many bins (spread strategy).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count as f64).recip();
        // Opening new bins is penalized more as stream progresses.
        score += 20.0 + 55.0 * progress - 15.0 * scarcity;
        // A new bin is good if the item is large relative to capacity.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global residual pressure: if mean residual across bins is small,
    // conserve space in roomy bins (prefer bins whose residual is below mean).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // Mild preference to fill bins that are already quite full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio;

    // Late in the stream, consolidate aggressively to avoid opening bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Discourage leaving residuals in the awkward 1..10 band (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress) - 0.35 * cap * norm_post * norm_post * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 12.0 * (1.0 - norm_post).powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.10 * (post - mean_residual).abs();

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * post / cap;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild preference for keeping bin count low early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * norm_post;

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance: residuals too small for plausible items are wasted.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // COMBINED: graded dead-space penalty (from best heuristic) plus
        // residual-lookahead coupling: penalize residuals that neither fit the
        // next item nor are large enough to be reusable.
        if dead_frac > 0.35 {
            score += 12.0 * (dead_frac - 0.35);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unreachable = (next_item_size - post_residual) as f64;
            if unreachable > 15.0 {
                score += 0.4 * unreachable.min(40.0);
            }
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        // Near-perfect chaining exists; avoid new bin.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        // COMBINED: if the only fitting bins would strand >30% dead space while
        // the next item is large, opening fresh is safer.
        if fitting_bins_count > 0 && next_item_size > 45 {
            let min_dead = if post_residual < next_item_size {
                (next_item_size - post_residual) as f64
            } else {
                0.0
            };
            if min_dead > 0.3 * bin_capacity as f64 {
                score -= 14.0;
            }
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 3.0;
            }
        }
        // Triple-chaining reward.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        // COMBINED: reward residuals that remain highly reusable (large enough
        // for typical items) after the chain.
        let chain_frac = two_step as f64 / bin_capacity.max(1) as f64;
        if chain_frac > 0.3 {
            score -= 3.0 * chain_frac.min(0.8);
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity-fraction buckets. Leftovers in "dead" classes (very small or
    // awkwardly mid-sized) are penalized; prime classes are rewarded.
    let pr = post_residual;
    let class = match pr {
        0 => 0,                       // perfect fit
        1..=9 => 1,                   // near-dead sliver
        10..=24 => 2,                 // small-item zone
        25..=49 => 3,                 // awkward middle
        50..=74 => 4,                 // half-bin usable
        _ => 5,                       // large usable
    };
    let class_penalty = [0.0, 14.0, 2.0, 9.0, 3.0, 0.0][class];
    score += class_penalty;

    // Integer-division harmonic: leftover mod 10 measures alignment with the
    // coarse item-size grid (items are multiples-ish of 10 in classic streams).
    let rem10 = (pr % 10) as f64;
    score += 0.6 * rem10;

    // Reward perfect / near-perfect fits strongly.
    if pr == 0 { score -= 40.0; }
    if pr > 0 && pr <= 5 { score -= 10.0; }

    // Lookahead coupling: does the leftover class admit the next item?
    if next_item_size > 0 {
        if (pr as u64) >= (next_item_size as u64) {
            // Next item still fits here: mildly good (keeps bin alive).
            score -= 4.0;
            // Harmonic bonus if leftover is exactly a "class match" for next item:
            let slack = pr - next_item_size;
            if slack == 0 { score -= 20.0; }
            else if slack <= 10 { score -= 6.0; }
            else if slack > 50 { score += 3.0; } // wasteful big gap
        } else {
            // This placement kills the bin for the next item.
            score += 8.0;
            // If leftover is in dead class anyway, killing it is fine.
            if class <= 1 { score -= 10.0; }
        }
    }

    // Last-chance logic: if this is the ONLY bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when no open bin offers a good (small) residual — i.e. when the
    // best available residual is large. Encode via mean_residual coupling:
    if bin_residual == bin_capacity {
        // Opening new bins is costly; penalize unless open bins are congested
        // (high mean residual means poor fits everywhere).
        let congestion = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 - 22.0 * congestion;
        // Late in the stream, avoid spawning bins that will never fill.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If many bins are open already, discourage another.
        score += 1.5 * open_bins_count as f64;
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (tighter bins) so loose bins stay available for large future items.
    let res_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    score += 6.0 * (res_frac - mean_frac);

    // Slight preference for tighter bins overall.
    score += 4.0 * (1.0 - res_frac);

    // Modulo-3 harmonic on item size: items in the "large" class (size%3==0
    // proxy for chunky items) should prefer tightest fits a bit more.
    if item_size % 3 == 0 && item_size > 50 {
        score += 0.15 * post_residual as f64;
    }

    score
}

