    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 3.0;
            }
        }
        // Triple-chaining reward.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        // COMBINED: extra reward when the chained residual stays below the
        // dead-space threshold, keeping bins compact.
        if two_step > 0 && (two_step as f64) < 0.1 * bin_capacity.max(1) as f64 {
            score -= 2.5;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (min item size historically >= 10), so punish them hard.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }
    // Slightly-better-but-still-awkward gaps [10, 19] get a mild penalty.
    if post_residual >= 10 && post_residual <= 19 {
        score += 10.0;
    }

    // Reward tight fits strongly (small post_residual is good if usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 9 && post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual,
    // reward keeping this bin.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: dead space likely.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 0 && post_residual <= 9 {
            score -= 20.0; // still worth it: avoids a fresh bin
        }
    }

    // Pressure from number of open bins: with many open bins, prefer
    // consolidating into existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base hesitation: prefer filling existing bins by default.
        score += 25.0;
        // But if no existing bin fits well (this call is the new-bin
        // candidate and it competes with a poor fit), the +25 can be
        // overcome by the poor fit's dead-space penalties.
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        // If mean residual across open bins is small, existing bins are
        // nearly full anyway -> new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is close to the item
    // (best-fit flavor) via deviation from mean residual.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 4.0;

    score
}

