        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }
    } else {
        // Perfect fill is the best outcome
        score -= 40.0;
    }

    // Penalize dead space: residuals too small for the smallest item (1..10)
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

