pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when post-fit gap tightly matches next item.
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly.
        score += 6.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Late in stream, new bins are less costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
    } else {
        // Last-chance bin before opening a new bin: reward using it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Reward using bins with above-average residual (balance load).
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance: residuals too small for plausible items are wasted.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // COMBINED: aggressive near-perfect fill reward (borrowed) fused with
        // fine-grained residual fitting — bonus grows with stream progress.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= (10.0 + 10.0 * progress) * (fill - 0.9);
        }
        // Penalize stranding: residual just below next item size.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        // Reward reusable mid-range residuals.
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        // Borrowed: prefer new bin when dead space would strand a large next item.
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 12.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
    }

    // Two-step lookahead with combined triple-chaining and progress scaling.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let it = item_size.max(1);
        if post_residual >= next_item_size + it {
            score -= 2.0;
            if post_residual >= next_item_size + it * 2 {
                score -= 3.0;
            }
            if post_residual >= next_item_size + it * 3 {
                score -= 2.0;
            }
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: bin residual exactly consumed
    // by current item + next item (chained perfect fit).
    if next_item_size > 0 {
        let chain = post_residual as f64 - next_item_size as f64;
        if chain == 0.0 {
            score -= 60.0; // perfect two-item chain: ideal placement
        } else if chain < 0.0 {
            // next item won't fit here; dead space stays for future items.
            // Reward small dead space, penalize large unusable gaps.
            let gap = post_residual as f64;
            if gap < 10.0 {
                score -= 15.0; // nearly-full bin is excellent
            } else if gap < next_item_size as f64 * 0.5 {
                score -= 6.0; // gap small relative to next item
            } else {
                score += (gap - next_item_size as f64) * 0.15; // wasted space penalty
            }
