            score -= 25.0 - chain.abs().min(25.0);
        }
    }

    // Relative fullness vs mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current bin
