pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, quadratically (dead space grows expensive).
    let mut score = norm_pr + 1.75 * norm_pr * norm_pr;

    // Strong discrete bonuses borrowed from best lineage:
    if post_residual == 0 {
        score -= 900.0; // perfect fill: overwhelming reward
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0; // exact two-step fit
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Smooth cubic coupling of residual with stream progress:
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score -= 1.2 * prog_poly * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // Mean residual context (junk-bin handling).
    if bin_residual != bin_capacity {
        let mean_res = mean_residual.max(1.0);
        let excess = (pr - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = norm_pr;
        if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 10.0 * (fill - 0.9);
        }
        // strand risk: residual close to but below next item is worst case
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
            score += 0.35 * closeness.min(25.0);
        }
        // reusable residual window
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // two-step chain rewards
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_step = post_residual - next_item_size;
            if two_step == 0 {
                score -= 15.0;
            } else if two_step <= 20 {
                score -= 0.5 * two_step as f64;
            } else if two_step <= 35 {
                score -= 3.0;
            }
            let it = item_size.max(1);
            if post_residual >= next_item_size + it {
                score -= 2.0;
                if post_residual >= next_item_size + 2 * it {
                    score -= 3.0;
                }
            }
        }
    }

    // New-bin candidate logic: open fresh bins early, close them off late;
    // also open a new bin when placing here would strand a large next item.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40;
        if bad_fit && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 12.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
    }

    score
}

