    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

