        }
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
        // NEW: open a fresh bin when item is huge and no open bin gives a near-perfect fit.
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if item_frac > 0.7 && fitting_bins_count > 0 && progress < 0.7 {
