            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
        // NEW: stronger chain reward when few bins can host the next item.
        if fitting_bins_count <= 2 && two_step <= 12 {
            score -= 3.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual (0 = perfect fit, 1 = empty bin)
    let x = pr / cap;

    // Smooth non-linear dead-space penalty: quadratic growth in waste
    let waste = x * x * (1.0 + 2.0 * progress);

    // Tightness coupling: reward fills more aggressively as stream progresses
    let fill_reward = -progress * (1.0 - x).powi(3) * 30.0;

    // Lookahead: penalize if next item cannot fit into post-residual
    let next_fits = (next_item_size as f64) <= pr && next_item_size > 0;
    let lookahead = if next_item_size == 0 {
        0.0
    } else if next_fits {
        -8.0 * (1.0 - (next_item_size as f64) / pr.max(1.0))
    } else {
        6.0 * (next_item_size as f64 / cap)
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -25.0
    } else {
        0.0
    };

    // Prefer dense bins relative to fleet mean residual
    let density = -(mean_residual - pr) * 0.15;

    // New-bin candidate: keep neutral-to-slightly-high so it's chosen only
    // when all open bins score badly (large waste), modulated by progress
    let new_bin_bias = if bin_residual == bin_capacity {
        10.0 + 20.0 * progress
    } else {
        0.0
    };

    let mut score = pr + waste * 40.0 + fill_reward + lookahead + last_chance + density + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small remainders are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: post_residual in (0,10] is nearly unusable for items >=10
    // (interface says sizes >=1 though), penalize tiny remainders less harshly than mid ones.
    if post_residual > 0 && post_residual <= 5 {
        score -= 60.0; // effectively dead, but at least it's a near-perfect fit
    } else if post_residual <= 15 {
        score += 10.0; // awkward dead zone
    }

    // Modulo-class logic on post_residual vs capacity: remainders that are
    // multiples of common small sizes (5,10,20,25) are re-usable.
    let reusable = |r: u32| r == 0 || r % 5 == 0 || r % 10 == 0 || r % 20 == 0 || r % 25 == 0;
    if reusable(post_residual) {
        score -= 25.0 + 0.15 * pr;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            score -= 0.5 * next_item_size as f64;
            if reusable(next_post) {
                score -= 30.0;
            }
            if next_post <= 5 {
                score -= 80.0;
            }
        } else {
            // next item won't fit here; penalize leaving large stranded space
            score += 0.3 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current item would leave a very awkward remainder in every open bin.
    if bin_residual == bin_capacity {
        // baseline score = capacity (100). Make new bins attractive only if
        // this is a large item or stream is early (bins can absorb future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.6 * cap + 0.4 * item_size as f64 - 40.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with residual close to item (tight fits) via
    // harmonic distance: |post_residual - mean_residual| small is fine.
    score += 0.05 * (pr - mean_residual).abs();

    // Slight tilt toward filling bins that are already half-full or more.
    let fill_frac = 1.0 - bin_residual as f64 / cap;
    if fill_frac > 0.5 {
        score -= 0.2 * fill_frac * item_size as f64;
    }

    // Small noise-free tiebreak by bin index proxy via open_bins_count pressure:
    // when many bins are open, prefer consolidating into existing ones.
    if open_bins_count > 4 {
        score -= 1.0 + 0.05 * open_bins_count as f64 * (bin_residual != bin_capacity) as u8 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
