pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue modulo 10
    let post_mod = post_residual % 10;
    // Dead-space penalty grows super-linearly for small nonzero residues (awkward classes)
    if post_residual > 0 {
        let awkward = match post_mod {
            1 | 2 | 3 => 6.0,
            4 | 5 | 6 => 3.0,
            7 | 8 | 9 => 1.0,
            _ => 0.0, // residue 0: perfectly reusable class
        };
        score += awkward * (10.0 - post_mod as f64);
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nmod = (post_residual - next_item_size) % 10;
            score -= 10.0 - (nmod as f64) * 0.8;
        } else {
            // next item cannot fit here: penalize leaving too-tight space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, offset by how full the stream is (early bins cheaper to open)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap + 10.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).min(10.0);
        // if no existing bin fits at all, opening is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for fuller bins (fraction of capacity used)
    score -= (item_size as f64 / cap) * 5.0;

    // Coupling with mean residual: prefer bins below the mean (tighten the tightest)
    score += ((mean_residual - bin_residual as f64).max(-20.0).min(20.0)) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance: residuals too small for plausible items are wasted.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Hard dead-space penalty scaled by item fraction.
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // Near-perfect fill bonus, stronger when competition is low.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // Penalize residuals just barely below next item (stranding risk).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        // Reward reusable residual windows for common small/mid sizes.
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
