    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1)
    // are worthless; anything below a practical threshold is heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fill
    } else if post_residual <= 10 {
        // Tiny gap: likely dead space -> strong penalty proportional to tightness
        score -= 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 20 {
