    if post_residual == 0 {
        score -= 300.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post gap,
    // this placement is excellent; if next item nearly fits, slight bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // next item won't fit here anyway; dead-space risk rises
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual <= 15 {
            score -= 40.0; // still fine: gap is dead space anyway
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.5;

    // Prefer bins below mean residual (filling emptier bins balances load),
    // but only mildly so dead-space logic dominates.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // New-bin candidate handling: empty bin should only win when the fit into
    // open bins would create large dead space or nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 25.0;
        // More expensive to open when many bins are already open
        score += open_pressure * 1.5;
        // Cheaper late in the stream (fewer future items to amortize? keep mild)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
        // Perfect fit now (item fills the whole bin) is great
        if item_size >= bin_capacity {
            score -= 400.0;
        }
    }

    // Tight-fit reward scaled by how much of the bin is consumed
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    score
}

