    // Dead-space avoidance for tiny residuals.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // Mid-range dead zones penalized unless next item chains in.
        if dead_frac >= 0.2 && dead_frac <= 0.4 {
            let chains = next_item_size > 0 && post_residual >= next_item_size;
            if !chains {
                score += 14.0 * (dead_frac - 0.2);
            }
        }
        // Reward near-perfect fills more aggressively as stream progresses.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9) * (0.5 + progress);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // Penalize residuals just below next item (worst-case stranding).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        // Reward residuals in the reusable common-size band.
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Reward mid-range reusable residuals when many bins compete.
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // Reward residuals reusable by common mid-size items.
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        // Penalize when this item leaves a hole smaller than itself (waste pattern).
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac && dead_frac < 0.45 {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Combined fine-grained fit + lookahead: prefer placements whose leftover
        // is either near-zero or exactly reusable, weighted by competition.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if leftover <= 3 {
                score -= 6.0 * (4.0 - leftover as f64);
            }
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        // Open new bin early if all fitting options would strand large next items.
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        // Penalize new-bin residuals too small to ever host mid-size items.
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        // Near-perfect chaining exists in an open bin; avoid new bin.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        // Discourage new bin when an open bin leaves a hole the next item absorbs.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
        // Avoid opening a new bin when any open bin can host the next item too
        // (two-step chain exists elsewhere); stronger late in the stream.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= bin_capacity - post_residual {
            score += 8.0 + 10.0 * progress;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        // Triple-chaining reward.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        // Exact-size chain bonus for small leftovers.
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Penalize dead space: residuals too small for typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Waste if the leftover can't fit the next item.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate emptier bins? no: fill fuller bins).
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Time horizon: early in stream, be conservative with new bins;
    // late in stream, avoid opening new bins at all costs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + progress * 60.0 + (open_bins_count as f64) * 2.0;
        // But early on, opening a bin is cheap.
        score -= (1.0 - progress) * 10.0;
    }

    // Fragmentation pressure: many open bins -> prefer filling existing ones harder.
    score -= (open_bins_count as f64).ln().max(0.0) * (100.0 - post_residual as f64) * 0.05;

    // Prefer exact-ish fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Slight tie-break noise-free determinism: bias by residual parity structure.
    if post_residual % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), non-linearly shaped
    let mut score = x * x * (2.0 - x) * cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, prefer tight fits strongly; later, tolerate slack to keep bins usable
    let progress_coupling = (1.0 - progress) * (x * x) - progress * (1.0 - x) * (1.0 - x);
    score += 20.0 * progress_coupling;

    // Penalize dead space that is too small to be useful for typical items,
    // weighted by how much of the stream remains
    let dead_zone = (1.0 - x).max(0.0);
    let small_gap_penalty = if x > 0.0 && x < 0.15 { (0.15 - x) * (0.15 - x) } else { 0.0 };
    score += 40.0 * (1.0 - progress) * small_gap_penalty;
    let _ = dead_zone;

    // Lookahead: reward bins whose post residual can fit the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    // Slight preference for bins with residuals near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect harmonic class match, heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio;

    // Harmonic class of post_residual: dead space that cannot host
    // any future item (>= min size) is worthless; penalize gently,
    // reward residuals that remain "usable".
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 40 {
        score -= 10.0; // sweet spot: hosts small/medium items
    }

    // Modulo-structure on post_residual: residuals that are multiples
    // of common item sizes (10,20,25,50) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin.
            score -= 15.0;
            if next_item_size == post_residual {
                score -= 30.0; // chain exact fit
            }
        } else {
            // Next item won't fit here; residual likely stranded.
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the final fitting bin
    // over opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> consolidate into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 3.0 * pressure.min(20.0);

    // Stream progression: early on, allow new bins; late, consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    // New-bin candidate (empty bin): add a fixed opening cost so it is
    // only chosen when all open bins score poorly.
    if bin_residual == bin_capacity {
        score += 55.0 + 35.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Residuals below the minimum item size (1) are impossible, but tiny
    // gaps (< 10) are effectively dead if future items are >= 10; under the
    // unknown-distribution interface items can be as small as 1, so weight
    // gaps that are too small for typical items more harshly.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 12.0 + (dead_threshold - post_residual) as f64 * 2.5;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin completely.
        score -= 25.0;
    }

    // Non-linear penalty on wasted residual: squared gap amplifies dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Open-bins pressure: when many bins are open, prefer consolidation
    // (avoid opening more); when few are open, tolerate new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + 2.0 * progress);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: add opening cost scaled by pressure.
        score += 8.0 + pressure * 2.0;
    } else {
        // Reward using an existing bin, more so under high pressure.
        score -= pressure * 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap: mild extra dead-space penalty.
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (tighter bins get priority, keeping loose bins available for big items).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

