            score += 0.35 * gap.min(25.0);
        }
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        if dead_frac > 0.35 {
            score += 12.0 * (dead_frac - 0.35);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unreachable = (next_item_size - post_residual) as f64;
            if unreachable > 15.0 {
