        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 45 {
            let min_dead = if post_residual < next_item_size {
                (next_item_size - post_residual) as f64
            } else {
                0.0
            };
            if min_dead > 0.3 * bin_capacity as f64 {
                score -= 14.0;
            }
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 12.0;
        }
        // refined: open new bin early if all fitting options would strand large next items
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
