        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
        let chain_frac = two_step as f64 / bin_capacity.max(1) as f64;
        if chain_frac > 0.3 {
            score -= 3.0 * chain_frac.min(0.8);
        }
    }

    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the bin after this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves leftover: reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack / 10.0);
        } else {
            // Next item cannot follow into this bin: penalize.
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 + gap * 0.3;
        }
    }

    // Penalize small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early in the stream, tolerate opening new bins slightly more (exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
