    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= pressure * 2.0;

    // Time horizon: early in stream, prefer compacting; late, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // New-bin candidate: only attractive when existing bins would leave big waste
    // or nothing fits well.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let waste_if_forced = (bin_residual - item_size) as f64;
        let poor_fit = waste_if_forced > 0.6 * bin_capacity as f64;
        if poor_fit && fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing).
    score -= 1.5 * (-( (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64 )).exp() * 5.0;

    score
}

