pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_n = pr / cap;

    // Base: post-residual, modulated by smooth progress polynomial
    let progress_poly = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_poly;

    // Non-linear penalty for small dead space (unusable residual)
    let dead = pr_n * pr_n * (1.0 - pr_n);
    score += 40.0 * dead * (1.0 - progress);

    // Perfect fit reward (smooth gaussian-like coupling)
    let fit_quality = 1.0 - (pr_n * 4.0).powi(2) * 0.25;
    score -= 25.0 * fit_quality.max(0.0);

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 10.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize spreading when many bins open; encourage consolidation
    score += (open_bins_count as f64).ln() * 2.0 * (item_size as f64 / cap);

    // New-bin candidate: make it moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
        score += 12.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance for tiny residuals.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills (combined with lookahead weighting).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let lookahead_fit = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
    score -= fill_ratio * (30.0 + 12.0 * lookahead_fit);

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // Mid-range dead zones penalized unless next item chains in.
        if dead_frac >= 0.2 && dead_frac <= 0.4 {
            let chains = next_item_size > 0 && post_residual >= next_item_size;
            if !chains {
                score += 14.0 * (dead_frac - 0.2);
            }
        }
        // Reward near-perfect fills more aggressively as stream progresses.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9) * (0.5 + progress);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // Penalize residuals just below next item (worst-case stranding).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        // Reward residuals in the reusable common-size band.
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Reward mid-range reusable residuals when many bins compete.
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // Reward residuals reusable by common mid-size items.
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        // Penalize when this item leaves a hole smaller than itself (waste pattern).
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac && dead_frac < 0.45 {
            score += 8.0 * (dead_frac - item_frac);
        }
        // New: penalize leaving residuals that no future item size plausibly matches
        // (residual far from any typical item granularity).
        if post_residual > 0 && post_residual < 100 && next_item_size > 0 {
            let dist = (post_residual as i32 - next_item_size as i32).unsigned_abs() as f64;
            if dist > 40.0 {
                score += 0.08 * (dist - 40.0);
            }
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
        // New: discourage new bin when some open bin achieves a near-exact fill
        // of the current item (tight-fit exists -> keep consolidation).
        if fitting_bins_count > 0 && item_size >= 60 {
            score += 12.0;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
        // New: chain-depth reward scaled by how much of the bin this consumes.
        let chain_use = (item_size + next_item_size) as f64 / bin_capacity.max(1) as f64;
        if chain_use > 0.85 {
            score -= 6.0 * (chain_use - 0.85);
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in some residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % 10; // decile residue class
    // Penalize odd / prime-ish residues more (they fit fewer common item sizes)
    let residue_penalty = match class {
        0 => -6.0,   // multiples of 10 fit many sizes
        2 | 4 | 6 | 8 => -3.0, // even residues are reusable
        5 => -1.0,
        _ => 2.5,    // odd residues are dead space
    };
    score += residue_penalty;

    // Integer-division thresholds on post_residual
    if post_residual <= 10 { score -= 12.0; }          // near-perfect fill
    else if post_residual <= 20 { score -= 5.0; }
    else if post_residual > 50 { score += 8.0; }       // leaving half a bin empty

    // Small post_residual that cannot fit the next item is wasted unless tiny
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // reward bins whose leftover can host the next item
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else if post_residual > 0 {
            score += 4.0 + pr / cap * 5.0; // stranded dead space
        }
        // Harmonic pairing: post_residual + next_item_size near capacity multiples
        let sum = post_residual + next_item_size;
        if sum % 100 <= 5 { score -= 4.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * open_bins_count as f64;
        if post_residual >= 80 { score -= 5.0; } // huge item, fresh bin is fine
    }

    // Tight fit reward
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 10.0 * tightness * tightness;

    // Progress-scaled consolidation: late in stream, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / cap);

    score
}

