        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        // Penalize when this item leaves a hole smaller than itself (waste pattern).
        let item_frac = item_size as f64 / cap;
        if dead_frac > 0.25 && item_frac < dead_frac && dead_frac < 0.45 {
            score += 8.0 * (dead_frac - item_frac);
        }
        // New: penalize leaving residual that wastes more than half the item size.
        if post_residual > 0 && (post_residual as f64) < item_frac * cap * 0.5 && item_size > 30 {
            score += 3.0;
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
        // New: discourage new bin when some open bin has near-perfect fit for this item.
        if fitting_bins_count > 0 && progress > 0.55 {
            score += 12.0;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
        // New: deeper lookahead — reward residuals that can absorb next two distinct sizes.
        if next_item_size > 0 && post_residual >= next_item_size * 2 + item_size.max(1) {
            score -= 3.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // Gaps below the minimum item size (1..10) are pure waste; gaps that
    // cannot hold a typical item (<= 20) are near-waste.
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual < 10 {
        score += 45.0;
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 30 {
        score += 6.0;
    }

    // If the lookahead item can use the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward when the next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // Residual too small even for the smallest future item: dead space.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (penalize the new-bin candidate) and encourage consolidation.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // Early in the stream, opening a bin is natural; soften penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    } else {
        // Favor bins tighter than the mean residual (good consolidation).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Prefer larger residual bins when item is big (avoid fragmenting big bins).
    if item_size > 60 {
        score += 0.15 * (bin_capacity - bin_residual) as f64;
    }

    score
}

