        score -= 120.0;
    }

    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
