        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
        // NEW: discourage new bin when any fitting bin would end nearly full
        if fitting_bins_count > 0 {
            score += 12.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
        // NEW: lookahead pair-fit — reward when next two items together fit leftover
        let two_items = next_item_size as u64 + item_size.max(1) as u64;
        if post_residual as u64 >= two_items * 2 {
            score -= 3.0;
        }
    }

    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

