            score -= 4.0;
        }
    }

    // Later in the stream, prefer consuming bins with large residuals (consolidation).
    score -= 0.1 * bin_residual as f64 * progress;

    // Mild penalty for deviating from the mean residual (keeps bin states balanced).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: quadratic in normalized post_residual, modulated by progress
    let pr_norm = (post_residual as f64 / cap).clamp(0.0, 1.0);
    let waste_curve = pr_norm * pr_norm * (1.0 + 2.0 * progress) - 0.5 * pr_norm;
    score += 20.0 * waste_curve;

    // Tight fits are rewarded more strongly as the stream progresses (smooth cubic progress term)
    let fit_tightness = 1.0 - pr_norm;
    score -= 15.0 * fit_tightness * (0.5 + 0.5 * progress * progress);

    // Lookahead coupling: penalize residual that cannot host the next item (smooth logistic gate)
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as f64;
        let gate = 1.0 / (1.0 + (-6.0 * (pr_norm - 0.5)).exp());
        score -= 12.0 * next_fits * gate;
        score += 8.0 * (1.0 - next_fits) * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.6 + 0.4 * progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * ((fitting_bins_count as f64).ln());
    }

    // Divergence from mean residual: mildly penalize outliers (quadratic coupling)
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff * diff / cap;

    // New-bin candidate: baseline penalty so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
