            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // Mid-range dead zones penalized unless next item chains in.
        if dead_frac >= 0.2 && dead_frac <= 0.4 {
            let chains = next_item_size > 0 && post_residual >= next_item_size;
