        if two_step >= 1 && two_step <= 6 {
            score -= 5.0;
        }
        // Deep lookahead: residual can absorb next item plus a mid-size follow-up.
        if next_item_size > 0 && post_residual >= next_item_size + 50 {
            score -= 2.5;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: dead-space quality classes via integer division thresholds
    let frac = post_residual as f64 / bin_capacity as f64;

    // Classify post_residual into harmonic classes (mod 10 bands)
    let class = post_residual / 10;
    let class_penalty = match class {
        0 => -8.0,          // near-perfect fit
        1..=2 => -4.0,      // small usable gap
        3..=5 => 0.0,       // medium gap
        6..=8 => 3.0,       // large gap, likely waste
        _ => 1.0,           // bin nearly empty after placement
    };
    score += class_penalty;

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Residual divisible by common item sizes => future-friendly gap
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
        if post_residual > 50 {
            score -= 5.0; // large item, fresh bin is fine
        }
    }

    // Lookahead coupling: prefer bins where next item also fits
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        // harmonic bonus if next item exactly consumes remaining space
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.0; // dead space relative to lookahead
    }

    // Stream progression: early on, be conservative about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(1) * 10 {
            score += 200.0 * (10.0 - post_residual as f64);
        }
