        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Reward mid-range reusable residuals when many bins compete.
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // Reward residuals reusable by common mid-size items.
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
