        // size (1..=100 window around mean residual) can consume, scaled by
        // how isolated this bin's residual is from the fleet mean.
        if post_residual > 0 && post_residual < 100 {
            let isolation = ((post_residual as f64 - mean_res).abs() / mean_res).min(2.0);
