        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
        // Combined mutation: when a fitting open bin would end near-perfectly
        // full, strongly prefer it over opening a fresh bin.
        if fitting_bins_count > 0 && post_residual > 0 {
            let cap = bin_capacity.max(1) as f64;
            if post_residual as f64 / cap < 0.08 {
                score += 20.0;
            }
        }
    }

