            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        // Triple-chaining reward.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        // Exact-size chain bonus for small leftovers.
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
        // Combined mutation: extend lookahead one more link when residual
        // remains large enough for a third consecutive fit.
        if post_residual >= next_item_size * 2 + item_size.max(1) {
            score -= 1.5;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward small residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 2.0; // mid-range residual is reusable by typical items
    }

    // Lookahead: if the next item can use the post-residual, reward this placement.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr <= post_residual as f64) && !is_new_bin {
            score -= 6.0;
        }
        // If next item is large and this bin would be left nearly full, that's fine.
        if nr > post_residual as f64 && post_residual < 15.0 {
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling: default penalty, relaxed when alternatives are poor.
    if is_new_bin {
        let mut penalty = 14.0;
        // Late in the stream, be more conservative about opening bins.
        penalty += 10.0 * progress;
        // If few bins fit and mean residual is small (poor alternatives), allow opening.
        if fitting_bins_count <= 1 {
            penalty -= 12.0;
        }
        if mean_residual < item_size as f64 * 0.6 {
            penalty -= 6.0;
        }
        // Large items pair well with fresh bins early on.
        if item_size > 60 && progress < 0.5 {
            penalty -= 5.0;
        }
        score += penalty;
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    // Global balance: prefer bins whose residual is close to the mean (avoid fragmentation).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tightness of the resulting fit (lower post_residual = better).
    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more heavily as the
    // stream progresses (late dead space is more costly since fewer chances remain).
    let norm_pr = pr / cap; // in [0,1)
    let decay = (progress * std::f64::consts::PI).sin().powi(2); // smooth in progress
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * decay);

    // Reward near-perfect fits with a smooth quadratic bonus (subtract score).
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 8.0;

    // Penalize creating residual that is too small to be useful later,
    // measured against the lookahead item size (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += 4.0 * g * g * cap;
        } else {
            // Post-residual can host the next item: reward smoothly.
            score -= 2.0 * (pr / (nxt + 1.0)).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count <= 1 {
        score -= 6.0;
    } else {
        score -= 6.0 / fitting_bins_count as f64;
    }

    // Mild pressure against bins deviating from the mean residual (smooth quadratic),
    // encouraging balanced residual distribution across open bins.
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    // New-bin candidate (empty bin): prefer it only when it yields a clean,
    // well-shaped residual; penalize it mildly otherwise so existing bins win ties.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * (1.0 - progress);
    }

    score
}

