    }

    // Prefer tighter existing bins: scale by fill fraction.
    score += (1.0 - (bin_residual as f64) / cap) * -8.0;

    // Stream progression: early on, be more willing to open bins (keep options);
    // late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 - progress * 4.0;

    // Mean-residual coupling: if this bin is much tighter than average, reward using it.
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

