pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 900.0; // perfect fill: extremely valuable
    }

    // Exact match with next item: reserve this bin for the follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Reward tight fits relative to bin residual.
    score -= 35.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).min(5.0);
    score += pressure * 4.0;

    // Mean-residual deviation: prefer tighter bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Two-step lookahead: residual hosting next item exactly or nearly.
