        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when current fit is bad and pressure high.
        let bad_fit = post_residual > 40;
        if bad_fit && open_bins_count > 2 {
            score -= 45.0;
        } else {
            score += 20.0;
        }
        // Late in the stream, opening new bins is cheap; early it is costly.
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        // Big next item that won't fit anywhere: better to start a fresh bin now.
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
    } else {
        // Existing bin: closeness of post_residual to next item is a soft penalty.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // Combined lookahead: reward residuals hosting a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
    }

    score
}

