    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual-relative analysis for open bins.
    let mean_res = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // High-fill rewards (borrowed from best-performing variant).
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // Near-miss penalty: leaving a hole just below next item size strands space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Combined lookahead: reward residuals that leave room for a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size
            && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = (post_residual.saturating_sub(next_item_size)) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0; // near-perfect chaining exists; avoid new bin
            }
        }
    } else {
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum plausible item size (1..20) are dead space.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Zero residual is perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize waste relative to bin capacity (tightness reward).
    score += (bin_capacity - post_residual) as f64 * 0.15;

    // Open bins pressure: fewer open bins is better; encourage filling existing bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // placement elsewhere creates severe dead space.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, new bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Mean residual coupling: placing in a bin far above mean residual
    // balances the pool, mildly rewarded.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits after this placement: mild reward proportional to leftover after both
            let two_step_left = post_residual - next_item_size;
            score -= 50.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            score += 0.3 * two_step_left as f64;
        } else {
            // next item won't fit here: penalize small dead space more
            let gap = next_item_size - post_residual;
            score += 0.5 * gap as f64;
        }
    }

    // Penalize creating dead space below the minimum plausible item size
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare against mean residual: prefer bins that are already tight (below mean residual)
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 400.0;
        if post_residual as f64 > mean_residual {
            score += 100.0;
        }
    }

    // Slight preference to fill fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * progress * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, especially near-perfect fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect/near-perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize small dead space that no future item (min size 1) can... actually
    // small residuals below typical item sizes are dead space; reward moderate residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space penalty
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0;
        }
        // if next item fits better than current bin could with full residual
        if bin_residual >= next_item_size && post_residual < next_item_size {
            // current item blocks next item; penalize mildly
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, prefer filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress;

    // New-bin candidate handling: empty bin gets high base cost unless
    // few bins are open or the fit here would be very poor
    if bin_residual == bin_capacity {
        let waste_if_used = bin_capacity - item_size;
        score = 55.0
            + 0.3 * waste_if_used as f64
            - 15.0 * progress
            - if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        // early stream: opening bins is cheap
        if open_bins_count < 3 {
            score -= 20.0;
        }
        // if item is huge, a fresh bin is natural
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling fuller bins (lower residual) when many bins open
    score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0) * (open_bins_count as f64).sqrt() / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted space, with polynomial shaping of post-residual.
    let mut score = pr_norm * pr_norm * cap + pr;

    // Smooth stream-progress coupling: waste tolerated early, punished late.
    let prog_coupling = pr_norm * (0.5 + 1.5 * progress * progress);
    score += prog_coupling * cap * 0.5;

    // Non-linear dead-space term: residuals that no plausible item can use.
    let dead = pr_norm * pr_norm * pr_norm * cap * 0.8;
    score += dead;

    // Lookahead: reward residual that fits the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n) / cap;
        let kernel = (-fit_gap * fit_gap * 8.0).exp();
        score -= 12.0 * kernel;
        // Penalize if next item barely misses this residual.
        let miss = if pr < n { (n - pr) / cap } else { 0.0 };
        score += 10.0 * miss * miss * cap * 0.1;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild competition penalty scaled by number of alternatives.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Tight-fit reward: near-perfect packing strongly favored.
    let tight = 1.0 - pr_norm;
    score -= 8.0 * tight * tight * tight;

    // Mean-residual coupling: prefer bins deviating smoothly from the mean.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.05;

    // Open-bin pressure: many open bins -> consolidate.
    score += 0.3 * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: fresh empty bin gets a smooth baseline cost
    // that shrinks as the stream progresses.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket residual into capacity-fraction classes.
    // Class 0: post_residual <= 10 (near-perfect fit) -> big reward.
    // Class 1: 11..=20 -> moderate reward.
    // Class 2: 21..=34 -> small reward.
    // Class 3+: dead space -> penalty scaled by class.
    let class = match post_residual {
        0..=10 => 0u32,
        11..=20 => 1,
        21..=34 => 2,
        35..=49 => 3,
        _ => 4,
    };
    let class_adjust: f64 = match class {
        0 => -18.0,
        1 => -10.0,
        2 => -4.0,
        3 => 6.0,
        _ => 14.0,
    };
    score += class_adjust;

    // Perfect fit gets an extra harmonic bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo harmonic: post_residual divisible by common item sizes (10,20,25)
    // is more likely reusable by future items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this residual: penalize large wasted residual.
            score += (post_residual as f64 - 20.0).max(0.0) * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 50 {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): post_residual = capacity - item_size.
    // Penalize opening a new bin unless it yields a very tight residual
    // (i.e., a large item) or existing fits are poor.
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64;
        score += 16.0; // default penalty for opening new bin
        if tightness <= 25.0 {
            score -= 30.0; // large item: starting fresh is fine
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
        // Many open bins with slack: discourage new bins.
        score += (open_bins_count as f64).min(20.0) * 0.6;
    }

    // Slight preference to fill bins that are already mostly full relative to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap zone: likely dead space unless next item is tiny.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // gap is actually usable by lookahead item
        } else {
            score += 30.0;
        }
    }

    // Reward tight fits (low post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // well, this placement chains nicely.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap: mild dead-space penalty scaled by gap.
        score += 0.15 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count and
        // mean residual available elsewhere.
        score += 45.0 + 4.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // If this is the last fitting bin, never open a new bin.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it before opening a new bin.
        score -= 35.0;
    }

    // Mild stream-progress modulation: late in the stream, waste tolerance
    // drops (less future to amortize dead space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leaving exactly the next item's size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Tight match: strong reward proportional to closeness.
        score -= 40.0 * (1.0 - diff / cap).max(0.0);
        // Exact match jackpot.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize dead space that next item cannot use.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward filling bins tighter than the fleet average (consolidation).
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild pressure to close out bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Slight penalty for fragmenting across many open bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Penalize small-but-nonzero dead space quadratically (unusable slivers).
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if it would leave awkward space
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to open/spread bins;
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress;

    // Global state: many open bins with high mean residual -> prefer using existing space.
    if open_bins_count > 2 {
        score += 0.3 * (open_bins_count as f64);
        if mean_residual > item_size as f64 * 1.5 {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: empty bin gets a calibrated penalty so it only wins
    // when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base penalty grows with progress (later => more reluctant to open new bins).
        score += 30.0 + 40.0 * progress;
        // But if the item is huge relative to capacity, a fresh bin is fine.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 35.0;
        }
        // If few bins are open early, opening is cheap.
        if open_bins_count <= 1 {
            score -= 30.0;
        }
    }

