    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: penalize residual quadratically, modulated by progress
    score += 30.0 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 20.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - pr_norm);
    }

    // Slight penalty when bin is far from mean residual (fragmentation signal)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: mild bias against opening new bins unless residual is tiny
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

