pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible into nice
    // chunks are more reusable than "dead" residues.
    let cap_frac = (bin_residual as f64) / (bin_capacity as f64);
    let post_frac = (post_residual as f64) / (bin_capacity as f64);

    // Classify post_residual into harmonic buckets via integer division.
    let post_class = post_residual / 10; // 0..=9 harmonic class
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when post_residual class matches next item's class (perfect refill).
    if next_item_size > 0 && post_class == next_class {
        score -= 25.0;
    }
    // Reward when next item fits exactly in the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize when next item cannot fit into post residual (wasted lookahead).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > 0 {
        score += 12.0;
    }
    // Penalize dead space: post_residual too small for the smallest plausible item (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo-based coupling: residuals that are multiples of common item
    // sizes (10, 20, 25, 50) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 { score -= 6.0; }
    if post_residual % 25 == 0 && post_residual > 0 { score -= 4.0; }
    if post_residual % 50 == 0 && post_residual > 0 { score -= 4.0; }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    if fill_ratio > 0.8 {
        score -= 15.0 * (fill_ratio - 0.8);
    } else if fill_ratio < 0.5 {
        score += 8.0 * (0.5 - fill_ratio);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // the stream is early or mean residual across bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Early stream: fresh bins are cheap. Later: penalize opening new bins
        // unless existing residuals are badly fragmented.
        score += 10.0 + 35.0 * (1.0 - progress) * -1.0 + 25.0 * (1.0 - fragmentation);
        if post_frac > 0.0 {
            // A fresh bin leaves a large usable residual; mild bonus.
            score -= 5.0;
        }
        // If several bins can fit, discourage opening a new one.
        if fitting_bins_count >= 2 {
            score += 15.0;
        }
    }

    // Mild global pressure: with many open bins, favor consolidating into
    // bins with below-mean residual (fill the emptier-feeling bins less).
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

