    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // disfavor opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 10.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (gap of <=5), slight reward too.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score -= 5.0;
    }

    // Prefer bins whose residual is below the mean (consolidating emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 900.0; // perfect fill: extremely valuable
    }

    // Exact match with next item: reserve this bin for the follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Reward tight fits relative to bin residual.
    score -= 35.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).min(5.0);
    score += pressure * 4.0;

    let mean_res = mean_residual.max(1.0);

    if bin_residual != bin_capacity {
        // Mean-residual deviation: prefer tighter bins (non-linear, capped).
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }

        // Dead-space fraction shaping.
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // Combined lookahead: reward residuals hosting a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
    }

    // Two-step lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when current fit is bad and pressure high.
        let bad_fit = post_residual > 40;
        if bad_fit && open_bins_count > 2 {
            score -= 45.0;
        } else {
            score += 20.0;
        }
        // Late in the stream, opening new bins is cheap; early it is costly.
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        // Big next item that won't fit anywhere: better to start a fresh bin now.
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain bonus: next item exactly fills the leftover space.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far off the chain is.
            score += diff * 0.8;
        }
        // Bonus if next item still fits after this placement (keeps chain alive).
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are "tight";
    // filling them is good (waste little), leaving them nearly empty is bad.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = post / mean_residual;
        // Reward consuming a below-average-residual bin heavily.
        if rel < 1.0 {
            score -= (1.0 - rel) * 25.0;
        } else {
            // Penalize dumping into an already-loose bin, worsening spread.
            score += (rel - 1.0) * 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize creating tiny unusable dead space (fragmentation).
    if post > 0 && post < 10.0 {
        score += 15.0;
    }
    // Slight reward for near-perfect fills of the bin.
    if post == 0 {
        score -= 20.0;
    }

    // Mild stream-progression pressure: as the stream advances, tighten packing
    // (favor fuller bins more aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Discourage opening new bins when reasonable open-bin options exist.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward bins whose leftover can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - lookahead_slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Leftover cannot fit next item: penalize dead space.
        score += 6.0;
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating very small, hard-to-use leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins with residual below the mean (compact bins first).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: early on, tolerate opening new bins less; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Mild pressure against spreading across many bins when item fits well.
    if post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance: residuals too small for plausible items are wasted.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual-relative analysis for open bins.
    let mean_res = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // High-fill rewards.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // Near-miss penalty: leaving a hole just below next item size strands space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Combined lookahead: reward residuals that leave room for a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size
            && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
        // NEW: fine-grained residual fitting — reward near-exact residual matches
        // against a plausible band of small item sizes (1..=12).
        if post_residual >= 1 && post_residual <= 12 {
            // tiny residual is nearly perfect: keep it but don't strand
            score -= 4.0;
        }
        // NEW: exact-halving structure — residual equal to half of capacity
        // is a reusable sweet spot.
        if post_residual * 2 == bin_capacity {
            score -= 5.0;
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = (post_residual.saturating_sub(next_item_size)) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0; // near-perfect chaining exists; avoid new bin
            }
        }
        // NEW: if any open bin leaves a residual that exactly matches the next
        // item, strongly discourage opening a new bin.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 40.0;
        }
        // NEW: when fitting bins are plentiful, new bins are wasteful.
        if fitting_bins_count >= 3 {
            score += 10.0;
        }
    } else {
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 40.0 * poly * cap;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.3 + 0.7 * progress);
    }

    // Penalize bins far below mean residual (fragmented bins)
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nx / cap) * progress;
        }
    }

    // Mild penalty for too many open bins relative to stream length
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when post_residual is large early, penalize late
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Base harmonic penalty: dead space quantized into capacity-fraction classes.
    // post_residual in [0, quarter)  -> tiny leftover, great fit
    // post_residual in [quarter, half) -> moderate leftover
    // post_residual >= half -> wasted big gap
    if post_residual < tenth {
        score -= 40.0; // near-perfect fit, strongly reward
    } else if post_residual < fifth {
        score -= 20.0;
    } else if post_residual < quarter {
        score -= 8.0;
    } else if post_residual < bin_capacity / 2 {
        score += 6.0;
    } else {
        score += 15.0; // big gap wasted
    }

    // Modulo-arithmetic harmonic: residual divisible by common small item sizes
    // (10..=20) means the leftover is reusable by typical items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            score += 3.0; // odd leftover, harder to reuse
        }
    }

    // Lookahead harmonic coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward proportionally to how snugly.
            let snug = (pr - next_item_size) as f64;
            score -= 18.0 - snug.min(18.0) * 0.5;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only before we place the current item here:
            // placing here may destroy that future slot; penalize mildly.
            score += 8.0;
        } else {
            score += 2.0;
        }
        // Harmonic class match: next item size class equals post-residual class
        let nclass = next_item_size / tenth;
        let pclass = pr / tenth;
        if nclass == pclass && pr >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < fifth {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good-fitting open bin exists. Penalize the
    // fresh bin by the number of open bins (prefer filling existing bins),
    // but relax when open bins are congested (high mean fill).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // If current item is small relative to capacity, opening a fresh bin
        // preserves flexibility for large future items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size <= bin_capacity / 3 {
            score -= 10.0 + 20.0 * (1.0 - progress);
        }
        // If mean residual across open bins is small, new bin becomes better.
        if mean_residual < (bin_capacity as f64) * 0.15 {
            score -= 35.0;
        }
    }

    // Prefer bins whose residual is close to mean (balance load mildly).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.1;
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance: residuals too small for plausible items are wasted.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        if dead_frac > 0.3 {
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // High-fill rewards.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9);
