        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Combined lookahead: reward residuals that leave room for a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size
            && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
        // NEW: extra reward when the follow-up pair chains exactly twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual <= 2 * next_item_size + 15 {
            score -= 4.0;
        }
        // NEW: penalize mid-range dead space when many bins compete (prefer tightest).
        if dead_frac > 0.2 && fitting_bins_count >= 4 {
            score += 6.0 * (dead_frac - 0.2);
        }
