        if fitting_bins_count > 0 && progress < 0.7 {
            score += 10.0 * (1.0 - progress);
        }
    } else {
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (min size 1..10
    // in the general case) are wasted. Penalize gaps below a usable threshold.
    let usable_threshold = 10u32;
    if post_residual < usable_threshold {
        score += 25.0 * (usable_threshold - post_residual) as f64;
    }

    // Reward tight fits (small post residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 12.0 * fill_ratio;
    }

    // Penalize leaving a gap that is "almost but not quite" a full small item,
    // which is classic dead space.
    if post_residual > 0 && post_residual < usable_threshold {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is excellent; encourage closing bins down.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline score near
    // capacity; make it attractive only when the current bin would waste a lot.
    if bin_residual == bin_capacity {
        // New bin: score = remaining capacity after placement, but apply
        // pressure so it's chosen only when existing bins fit poorly.
        score = bin_capacity as f64 - item_size as f64;
        if fitting_bins_count >= 1 {
            // There is an existing bin that fits; require a very poor fit there
            // to justify opening a new bin.
            let poor_fit = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * (1.0 - poor_fit);
            score += 3.0 * open_bins_count as f64;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Existing bin: bonus if it can also accommodate the next item after
        // this placement (lookahead synergy).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize if placing here strands the next item (gap too small for it).
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
        // Mean residual coupling: prefer bins with residual far below mean
        // (tighten the tightest bins first, keep loose bins flexible).
        let dev = mean_residual - post_residual as f64;
        score += 0.05 * dev;
    }

    // Mild stream-progress term: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

