            // next item won't fit; penalize leaving a gap it can't use
            score += 30.0 + (nxt - post_residual as f64) * 0.5;
        }
    }

    // Relative-to-mean adjustment: prefer bins tighter than average.
    let resid = post_residual as f64;
    score += (resid - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.3;
        // early stream: allow opening bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    score
}

