        score += 0.15 * (post_residual as f64 - 50.0);
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: prefer bins whose post_residual still fits the next item,
    // penalize bins that would leave a residual the next item cannot use.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // If next item exactly fills post_residual, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Global state coupling: prefer filling bins with below-average residual
    // (consolidate space), penalize draining already-tight bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: score relative to mean residual and progress.
        score = bin_capacity as f64 * (0.6 + 0.4 * progress) - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else {
        score -= 15.0 * progress * (fitting_bins_count as f64);
    }

    // Mild penalty for proliferating open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted space (dead space grows super-linearly in cost)
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 10.0;

    // Smooth cubic coupling of residual waste with stream progress:
    // early on, waste is cheap (bins are cheap); later, waste is costly.
    let prog_term = progress * progress * (3.0 - 2.0 * progress);
    score += norm_pr * norm_pr * norm_pr * 40.0 * (0.5 + prog_term);

    // Reward tight fits: small post_residual relative to item size.
    score -= (1.0 - norm_pr).powi(3) * 12.0;

    // Lookahead: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Smooth penalty if next item cannot use the leftover space, scaled by leftover size.
        score += norm_pr * 6.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smoothly weighted by progress).
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.6 + 0.4 * prog_term);
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, smooth quadratic term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 4.0;

    // New-bin candidate: empty bin should only win when its residual advantage
    // outweighs consolidation; give it a smooth offset penalty.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - prog_term) - 5.0 * (1.0 - norm_item);
    }

    score
}

