    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // denominators are more "reusable" by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony: f64 = 0.0;
        if pr % 2 == 0 { harmony += 2.0; }
        if pr % 5 == 0 { harmony += 3.0; }
        if pr % 10 == 0 { harmony += 4.0; }
        if pr % 20 == 0 { harmony += 3.0; }
        if pr % 25 == 0 { harmony += 2.0; }
        if pr % 50 == 0 { harmony += 5.0; }
        score -= harmony;

        // Dead-space penalty: tiny unusable residues (modular "orphan" classes)
        if pr < 10 { score += 12.0; }
        else if pr < 15 { score += 5.0; }
    } else {
        // Perfect fit is ideal
        score -= 25.0;
    }

    // Integer-division thresholds on post_residual vs next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here too: strong reward
            score -= 8.0;
            // Bonus if post_residual is an exact harmonic multiple of next size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            // Chain fit: next item's post-residual also small-but-usable
            let chain = post_residual - next_item_size;
            if chain % 10 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit: penalize proportionally to wasted harmony
            score += 4.0;
            if next_item_size > post_residual && post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current bin's
    // post-residual would be a poor harmonic class and item is large.
    if bin_residual == bin_capacity {
