    // New-bin candidate adjustment: an empty bin has bin_residual == bin_capacity;
    // discourage it unless the fit in existing bins is terrible (handled by
    // dead-space penalties above). Add a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

