pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead reward: if the next item can also fit into the leftover space,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.15;
    }

    // Penalize dead space: leftover too small for the minimum item size (1..100
    // interface, assume small items may appear, but a tiny residual is still
    // mostly wasted relative to bin capacity).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin, but
    // relax the penalty late in the stream and when existing bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 15.0 * progress;
        // If open bins are nearly full on average, a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // If many bins can fit the item, definitely prefer an existing one.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Slight preference for bins whose current residual is tight relative
    // to capacity (best-fit flavor beyond raw post_residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Slight time-horizon modulation: early in the stream, be a bit more
    // conservative about wasting space (favor tight fits), late in the
    // stream just close out bins quickly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        if dead_frac > 0.35 {
            score += 12.0 * (dead_frac - 0.35);
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac {
            score += 8.0 * (dead_frac - item_frac);
        }
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // combined lookahead: reward residuals that leave room for a plausible follow-up pair
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
    }

    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40;
        if bad_fit && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
    } else {
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
    }

    // Two-step lookahead chain rewards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits via a smooth cubic in fill
    score -= 12.0 * fill * fill * fill;

    // Penalize dead space that is too small to be useful (smoothly)
    let dead = pr / cap;
    score += 20.0 * dead * (1.0 - dead) * (1.0 - dead) * (1.0 - dead);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        if diff >= 0.0 {
            score -= 6.0 * (diff / cap);
        } else {
            score += 4.0 * (-diff / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Slight pull toward bins near the mean residual (balance)
    score += 0.2 * (pr - mean_residual).abs();

    score
}

