pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance for tiny residuals.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        // Hard dead-space penalty scaled by item size.
        if dead_frac > 0.3 {
            let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        // Mid-range dead zones penalized unless next item chains in.
        if dead_frac >= 0.2 && dead_frac <= 0.4 {
            let chains = next_item_size > 0 && post_residual >= next_item_size;
            if !chains {
                score += 14.0 * (dead_frac - 0.2);
            }
        }
        // Reward near-perfect fills more aggressively as stream progresses.
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9) * (0.5 + progress);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        // Penalize residuals just below next item (worst-case stranding).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 6.0 {
                score += 6.0 - closeness;
            }
        }
        // Reward residuals in the reusable common-size band.
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        // Reward mid-range reusable residuals when many bins compete.
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        // Reward residuals reusable by common mid-size items.
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        // Penalize when this item leaves a hole smaller than itself (waste pattern).
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac && dead_frac < 0.45 {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Combined lookahead: reward residuals that leave room for a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
    }

    // New-bin candidate logic with time-varying pressure.
    if bin_residual == bin_capacity {
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        // Open new bin early if all fitting options would strand large next items.
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        // Penalize new-bin residuals too small to ever host mid-size items.
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        // Near-perfect chaining exists in an open bin; avoid new bin.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        // Discourage new bin when an open bin leaves a hole the next item absorbs.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        if post_residual >= next_item_size + item_size.max(1) {
            score -= 2.0;
            if post_residual >= next_item_size + item_size.max(1) * 2 {
                score -= 4.0;
            }
        }
        // Triple-chaining reward.
        if post_residual >= next_item_size + item_size.max(1) * 3 {
            score -= 2.0;
        }
        // Exact-size chain bonus for small leftovers.
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which fraction-of-capacity band does it fall in?
    let item_class = item_size / 10; // 0..=10 (item sizes 1..100)
    let post_class = post_residual / 10; // 0..=10

    // Reward placements that leave post_residual in "usable" harmonic classes:
    // post residuals that are multiples of common item sizes (multiples of 10)
    // are more likely to be exactly filled by future items.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.0;
    }

    // Penalize dead space: post_residual in awkward middle bands (11..29 mod 30)
    let awkward = post_residual % 30;
    if awkward >= 11 && awkward <= 29 {
        score += 4.0;
    }

    // Perfect fit is best
    if post_residual == 0 {
        score -= 25.0;
    }

    // Class matching: if post_residual class equals a plausible next-item class,
    // the next item may exactly consume it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // exact fill next step
        } else if next_item_size <= post_residual {
            let nclass = next_item_size / 10;
            if nclass == post_class && post_class > 0 {
                score -= 5.0;
            }
            score -= (post_residual as f64) * 0.05;
        } else {
            // next item cannot fit here anyway; slightly favor keeping flexibility
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so we only
    // open a new bin when all open bins are tightly packed or would waste space.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins have small residuals
        // (high packing density) or few bins fit the item.
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * 0.55 - tightness * 20.0
            - (fitting_bins_count as f64) * 1.5
            - (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0; // big item coming: fresh bin useful
        }
        if post_residual == 0 {
            score = 1e9; // never "open" a bin for a zero-residual phantom
        }
    }

    // Slight preference for bins with below-mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 900.0;
    }
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Dead-space avoidance for tiny residuals.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fills.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    let mean_res = mean_residual.max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual != bin_capacity {
        let excess = (post_residual as f64 - mean_res) / mean_res;
        if excess > 1.1 {
            score += 18.0 * (excess - 1.1).min(3.2);
        } else if excess < -0.5 {
            score -= 4.0 * (-excess - 0.5).min(2.0);
        }
        let dead_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.35 && next_item_size > post_residual {
            score += 12.0 * (dead_frac - 0.35);
        } else if dead_frac < 0.12 {
            score -= 6.0 * (0.12 - dead_frac);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(25.0);
        }
        if dead_frac > 0.3 {
            let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
            score += 10.0 * (dead_frac - 0.3) * (1.0 + item_frac);
        }
        if dead_frac >= 0.2 && dead_frac <= 0.4 {
            let chains = next_item_size > 0 && post_residual >= next_item_size;
            if !chains {
                score += 14.0 * (dead_frac - 0.2);
            }
        }
        let fill = 1.0 - dead_frac;
        if fill > 0.9 {
            score -= 12.0 * (fill - 0.9) * (0.5 + progress);
        }
        if fill > 0.95 && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        if fill > 0.92 && post_residual >= 20 && post_residual <= 70 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let closeness = (next_item_size - post_residual) as f64;
            if closeness <= 8.0 {
                score += (8.0 - closeness) * 1.2;
            }
        }
        if post_residual >= 25 && post_residual <= 60 {
            score -= 3.0;
        }
        if post_residual >= 30 && post_residual <= 55 && fitting_bins_count >= 3 {
            score -= 2.0;
        }
        if post_residual >= 50 && post_residual <= 100 {
            score -= 1.5;
        }
        let item_frac = item_size as f64 / bin_capacity.max(1) as f64;
        if dead_frac > 0.25 && item_frac < dead_frac && dead_frac < 0.45 {
            score += 8.0 * (dead_frac - item_frac);
        }
        // Combined lookahead: reward residuals that leave room for a plausible follow-up pair.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 30 && fitting_bins_count <= 3 {
            score -= 3.5;
        }
    }

    if bin_residual == bin_capacity {
        if post_residual > 40 && open_bins_count > 2 {
            score -= 45.0;
        }
        score -= 60.0 * (1.0 - progress);
        score += 40.0 * progress;
        if progress > 0.5 {
            score += 30.0;
        }
        if progress > 0.75 && open_bins_count > 1 {
            score += 25.0;
        }
        if next_item_size > post_residual && next_item_size > 60 {
            score -= 22.0;
        }
        if open_bins_count > 4 && fitting_bins_count > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && progress > 0.3 {
            score += 6.0 * progress;
        }
        if post_residual > 60 && next_item_size > post_residual {
            score -= 10.0;
        }
        if post_residual > 45 && next_item_size > post_residual && next_item_size > 50 {
            score -= 14.0;
        }
        if next_item_size > post_residual && next_item_size > 70 && progress < 0.4 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 && progress < 0.6 {
            score += 6.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual >= 20 {
            score += 15.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let worst_case_gap = post_residual.saturating_sub(next_item_size) as f64;
            if worst_case_gap > 0.0 && worst_case_gap < 8.0 {
                score -= 6.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 30 {
                score += 10.0;
            }
        }
    }

    // Two-step lookahead: does the next item also fit well after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == 0 {
            score -= 15.0;
        } else if two_step <= 20 {
            score -= 0.5 * two_step as f64;
        } else if two_step <= 35 {
            score -= 3.0;
        }
        let need = item_size.max(1);
        if post_residual >= next_item_size + need {
            score -= 2.0;
            if post_residual >= next_item_size + need * 2 {
                score -= 4.0;
            }
        }
        if post_residual >= next_item_size + need * 3 {
            score -= 2.0;
        }
        if two_step >= 1 && two_step <= 6 {
            score -= 4.0;
        }
    }

    // Mild consolidation toward larger-residual bins.
    score += (bin_residual as f64 - mean_res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A gap is "dead" if it cannot fit even the smallest plausible item (<= 10),
    // and increasingly bad the smaller the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 40.0;
    }

    // Penalize gaps too small for the lookahead item (waste relative to what's next).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        let deficit = (next_item_size as u32 - post_residual) as f64;
        score += deficit * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Open-bin pressure: discourage scattering across many bins; encourage
    // filling existing bins when bin count is high.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins less attractive unless the fit is
    // genuinely bad in existing bins (post_residual already dominates).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Slight stream-progression tilt: as the stream matures, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect match between post_residual and next_item_size is ideal
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight matches for the next item
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Penalize post_residual that is too small for the next item (dead space)
        if (post_residual as u64) < next_item_size as u64 && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal post_residual
        score += 0.0;
    }

    // Relative to mean residual: bins with residual close to mean are neutral;
    // prefer placing into bins with residual below mean (tightening them)
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        score += 15.0;
    }

    // Slight preference for filling tighter bins overall
    score -= 0.2 * (bin_residual - post_residual) as f64;

    // Small penalty for tiny unusable post_residual (dead space) unless it's near zero
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
